package com.yeyamo_mobile.api.notification_service.newsletter;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.Instant;import java.util.*;import java.util.concurrent.CompletableFuture;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.kafka.core.KafkaTemplate;
class NewsletterApplicationServiceTest {
 @Test void duplicateSendPublishesOnlyOnce(){var campaigns=mock(NewsletterCampaignRepository.class);var stats=mock(NewsletterCampaignStatsRepository.class);@SuppressWarnings("unchecked")KafkaTemplate<String,String> kafka=mock(KafkaTemplate.class);var entity=new NewsletterCampaignEntity();entity.id=UUID.randomUUID();entity.name="N";entity.subject="S";entity.content="C";entity.segmentJson="{}";entity.status=NewsletterStatus.DRAFT;entity.createdBy="admin";entity.createdAt=Instant.now();entity.updatedAt=entity.createdAt;when(campaigns.findById(entity.id)).thenReturn(Optional.of(entity));when(campaigns.save(any())).thenAnswer(i->i.getArgument(0));when(kafka.send(anyString(),anyString(),anyString())).thenReturn(CompletableFuture.completedFuture(null));var service=new NewsletterApplicationService(campaigns,stats,new ObjectMapper().findAndRegisterModules(),kafka,"newsletter.dispatch");service.send(entity.id);var firstKey=entity.dispatchKey;assertNotNull(firstKey);service.send(entity.id);verify(kafka,times(1)).send(anyString(),anyString(),anyString());assertEquals(firstKey,entity.dispatchKey);}
}
